-- 115 AI conversation groups; forward-only, idempotent.
SET @schema_name=DATABASE();
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation_group'),'CREATE TABLE `fun_ai_conversation_group` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`admin_id` bigint unsigned NOT NULL,`name` varchar(100) NOT NULL,`created_at` datetime NULL,`updated_at` datetime NULL,`deleted_at` datetime NULL,PRIMARY KEY (`id`),UNIQUE KEY `uk_ai_conversation_group_owner_name` (`admin_id`,`name`),KEY `idx_ai_conversation_group_owner` (`admin_id`,`deleted_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation' AND COLUMN_NAME='group_id'),'ALTER TABLE `fun_ai_conversation` ADD COLUMN `group_id` bigint unsigned NULL AFTER `admin_id`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation' AND COLUMN_NAME='is_archived'),'ALTER TABLE `fun_ai_conversation` ADD COLUMN `is_archived` tinyint(1) NOT NULL DEFAULT 0 AFTER `status`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation' AND COLUMN_NAME='is_unread'),'ALTER TABLE `fun_ai_conversation` ADD COLUMN `is_unread` tinyint(1) NOT NULL DEFAULT 0 AFTER `is_archived`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation' AND INDEX_NAME='idx_ai_conversation_group'),'ALTER TABLE `fun_ai_conversation` ADD KEY `idx_ai_conversation_group` (`admin_id`,`group_id`,`is_archived`,`updated_at`)','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_conversation' AND CONSTRAINT_NAME='fk_ai_conversation_group'),'ALTER TABLE `fun_ai_conversation` ADD CONSTRAINT `fk_ai_conversation_group` FOREIGN KEY (`group_id`) REFERENCES `fun_ai_conversation_group` (`id`) ON DELETE SET NULL ON UPDATE CASCADE','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
